// ===========================================================================
//  CẤU HÌNH
// ===========================================================================
const WATCHLIST = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'SSI', 'DGC', 'VND', 'MBB', 'STB'];

// true = gửi báo cáo cả khi hôm nay không phải ngày giao dịch (để test)
const TEST_MODE = false;

const LOOKBACK_DAYS = 10;  // số phiên gần nhất để xét chuỗi gom/xả
const STREAK_MIN    = 3;   // gom/xả liên tiếp từ N phiên -> tín hiệu
const BIG_NET_TY    = 20;  // |mua/bán ròng| 1 phiên >= N tỷ -> tín hiệu mạnh
const NET_MIN_TY    = 1;   // |ròng| < N tỷ coi là trung tính (không tính chuỗi)
// ===========================================================================

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': 'application/json',
  'Referer': 'https://dstock.vndirect.com.vn/',
};

const todayStr = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' }); // YYYY-MM-DD
const sign = (v) => (v >= NET_MIN_TY ? 1 : v <= -NET_MIN_TY ? -1 : 0);
const fmtTy = (v) => (v >= 0 ? '+' : '') + v.toFixed(1) + ' tỷ';

const rows = [];
const signals = [];
const debug = [];
let latestDate = '';

for (const ticker of WATCHLIST) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + ticker + '&size=' + LOOKBACK_DAYS + '&sort=tradingDate:desc',
      headers,
      json: true,
      timeout: 20000,
    });
    const ses = (res && res.data) || [];
    if (!ses.length) { debug.push(ticker + ': không có dữ liệu'); continue; }

    if (ses[0].tradingDate > latestDate) latestDate = ses[0].tradingDate;
    const nets = ses.map(s => (s.netVal || 0) / 1e9); // tỷ đồng, phiên mới nhất trước

    // Chuỗi hiện tại (gom hoặc xả liên tiếp)
    const s0 = sign(nets[0]);
    let streak = 0, total = 0;
    while (streak < nets.length && s0 !== 0 && sign(nets[streak]) === s0) {
      total += nets[streak];
      streak++;
    }

    // Chuỗi liền trước (để bắt đảo chiều)
    let j = streak;
    const s1 = j < nets.length ? sign(nets[j]) : 0;
    let prevLen = 0, prevTotal = 0;
    while (j < nets.length && s1 !== 0 && sign(nets[j]) === s1) {
      prevTotal += nets[j];
      prevLen++;
      j++;
    }

    debug.push(ticker + ': OK (' + ses.length + ' phiên, ròng hôm nay ' + fmtTy(nets[0]) + ')');

    // Dòng tổng quan
    const emoji = s0 > 0 ? '🟢' : s0 < 0 ? '🔴' : '⚪';
    let line = emoji + ' *' + ticker + '* ' + fmtTy(nets[0]);
    if (streak >= 2) line += '  _(' + (s0 > 0 ? 'gom' : 'xả') + ' ' + streak + ' phiên, ' + fmtTy(total) + ')_';
    rows.push({ ticker, net: nets[0], line });

    // Tín hiệu
    if (Math.abs(nets[0]) >= BIG_NET_TY) {
      signals.push('🔥 *' + ticker + '*: ' + (nets[0] > 0 ? 'MUA' : 'BÁN') + ' ròng mạnh ' + fmtTy(nets[0]) + ' trong phiên');
    }
    if (streak >= STREAK_MIN) {
      signals.push((s0 > 0 ? '📈' : '📉') + ' *' + ticker + '*: khối ngoại ' + (s0 > 0 ? 'gom' : 'xả') + ' *' + streak + ' phiên liên tiếp*, tổng ' + fmtTy(total));
    }
    if (s0 !== 0 && s1 === -s0 && prevLen >= STREAK_MIN) {
      signals.push('🔄 *' + ticker + '*: ĐẢO CHIỀU — sau ' + prevLen + ' phiên ' + (s1 > 0 ? 'gom (' : 'xả (') + fmtTy(prevTotal) + ') chuyển sang ' + (s0 > 0 ? 'mua ' : 'bán ') + fmtTy(nets[0]));
    }
  } catch (e) {
    debug.push(ticker + ': ❌ ' + (e.message || String(e)));
  }
}

// Không phải ngày giao dịch (dữ liệu mới nhất không phải hôm nay) -> không gửi
if (!TEST_MODE && latestDate && latestDate !== todayStr) {
  return [{ json: { hasAlerts: false, reason: 'Hôm nay không phải ngày giao dịch (dữ liệu mới nhất: ' + latestDate + ')', debug } }];
}
if (!rows.length) {
  return [{ json: { hasAlerts: false, reason: 'Không lấy được dữ liệu mã nào', debug } }];
}

rows.sort((a, b) => Math.abs(b.net) - Math.abs(a.net));
const totalNet = rows.reduce((s, r) => s + r.net, 0);

const sections = [];
if (signals.length) sections.push('🚨 *TÍN HIỆU ĐÁNG CHÚ Ý*\n\n' + signals.join('\n'));
sections.push('📊 *TOÀN CẢNH WATCHLIST* — tổng ròng ' + fmtTy(totalNet) + '\n\n' + rows.map(r => r.line).join('\n'));

const dateVN = (latestDate || todayStr).split('-').reverse().join('/');
const message = (TEST_MODE ? '🧪 *TEST* — ' : '')
  + '💰 *DÒNG TIỀN KHỐI NGOẠI* — ' + dateVN + '\n\n'
  + sections.join('\n\n———\n\n')
  + '\n\n_Nguồn: VNDirect · ròng = mua − bán_';

return [{ json: { hasAlerts: true, message, debug } }];
